        result: bytes | UStr | None = value
    else:
        result = None
        encodings: list[str] = []
        if encoding and encoding not in encodings:
            encodings.append(encoding)
        if ENCODING not in encodings:
            encodings.append(ENCODING)
        if fallback and fallback not in encodings:
            encodings.append(fallback)
        for enc in _encoding_tests:
            if enc not in encodings:
                encodings.append(enc)

        for enc in encodings:
            try:
                decoded = value.decode(enc, errors)
                result = UStr(decoded, enc)
                break
            except ValueError:
                pass

        if result is None:
            decoded = value.decode(ENCODING, errors='ignore')
            result = UStr(decoded, ENCODING)

    return result

