def mousePressEvent(self, event):
    if event.button() != Qt.LeftButton:
        super().mousePressEvent(event)
        return
    pos = event.pos()
    for rect, text, is_head, original_tag in self._label_hits:
        if not rect.contains(pos):
            continue
        graph_view = self._graph_view()
        if graph_view is not None and graph_view.is_in_merge_mode():
            if is_head:
                # HEAD is not a valid merge target.
                event.accept()
                return
            graph_view.complete_merge(text)
            event.accept()
            return
        if is_head:
            qtutils.set_clipboard(text)
            event.accept()
            return
        self._show_branch_menu(event, text, original_tag)
        event.accept()
        return
    super().mousePressEvent(event)

def _graph_view(self):
    scene = self.scene()
    if scene is None:
        return None
    views = scene.views()
    if not views:
        return None
    view = views[0]
    if isinstance(view, GraphView):
        return view
    return None

def _current_branch_name(self):
    view = self._graph_view()
    if view is None or view.context is None:
        return None
    model = view.context.model
    if model is None:
        return None
    return getattr(model, 'currentbranch', None) or None

def _modified_paths(self):
    view = self._graph_view()
    if view is None or view.context is None:
        return []
    model = view.context.model
    if model is None:
        return []
    return list(getattr(model, 'modified', None) or [])

def _show_branch_menu(self, event, full_name, original_tag):
    is_local_branch = original_tag.startswith('heads/')
    agent_part = _agent_branch_part(full_name)
    menu = QtWidgets.QMenu()
    copy_full = menu.addAction(N_('Copy "%s"') % full_name)
    copy_part = None
    if agent_part is not None:
        copy_part = menu.addAction(N_('Copy "%s"') % agent_part)
    menu.addSeparator()
    checkout = menu.addAction(N_('Checkout "%s"') % full_name)
    rename = None
    rename_to = None
    rename_to_target = None
    rewind_check = None
    rewind_paths = []
    if is_local_branch:
        rename = menu.addAction(N_('Rename "%s"...') % full_name)
        graph_view = self._graph_view()
        if graph_view is not None:
            basenames = _branch_tip_basenames(
                graph_view.context, getattr(self.commit, 'oid', None)
            )
            if basenames:
                rename_to_target = '%s/%s' % (full_name, ','.join(basenames))
                rename_to = menu.addAction(
                    N_('Rename to "%s"...') % rename_to_target
                )
        if self._current_branch_name() == full_name:
            rewind_paths = self._modified_paths()
            if rewind_paths:
                rewind_check = menu.addAction(N_('Rewind check'))
    merge_to = menu.addAction(N_('Merge to...'))
    push_actions = []
    push_force_actions = []
    push_all_action = None
    push_force_all_action = None
    if is_local_branch:
        remotes = self._configured_remotes()
        if remotes:
            menu.addSeparator()
            push_menu = menu.addMenu(N_('Push "%s" to') % full_name)
            push_menu.setIcon(icons.push())
            for remote in remotes:
                action = push_menu.addAction(remote)
                push_actions.append((action, remote))
            if len(remotes) > 1:
                push_menu.addSeparator()
                push_all_action = push_menu.addAction(N_('All remotes'))
            push_menu.addSeparator()
            for remote in remotes:
                action = push_menu.addAction(
                    N_('%s (force-with-lease)') % remote
                )
                push_force_actions.append((action, remote))

                if len(remotes) > 1:
                    push_force_all_action = push_menu.addAction(
                        N_('All remotes (force-with-lease)')
                    )
        chosen = menu.exec_(event.screenPos())
        if chosen is None:
            return
        if chosen is copy_full:
            qtutils.set_clipboard(full_name)
        elif copy_part is not None and chosen is copy_part:
            qtutils.set_clipboard(agent_part)
        elif chosen is checkout:
            graph_view = self._graph_view()
            if graph_view is None:
                return
            result = cmds.do(cmds.CheckoutBranch, graph_view.context, full_name)
            if result and result[0] == 0:
                graph_view.merge_finished.emit()
        elif rename is not None and chosen is rename:
            self._rename_branch(full_name, suggestion=full_name)
        elif rename_to is not None and chosen is rename_to:
            self._rename_branch(full_name, suggestion=rename_to_target)
        elif rewind_check is not None and chosen is rewind_check:
            graph_view = self._graph_view()
            if graph_view is not None:
                from . import rewind as rewind_widget

                rewind_widget.run_rewind_check(
                    graph_view.context, full_name, rewind_paths
                )
                graph_view.merge_finished.emit()
        elif chosen is merge_to:
            graph_view = self._graph_view()
            if graph_view is not None:
                graph_view.enter_merge_mode(full_name)
        elif push_all_action is not None and chosen is push_all_action:
            self._push_branch(full_name, [r for _, r in push_actions], force=False)
        elif push_force_all_action is not None and chosen is push_force_all_action:
            self._push_branch(
                full_name, [r for _, r in push_force_actions], force=True
            )
        else:
            for action, remote in push_actions:
                if chosen is action:
                    self._push_branch(full_name, [remote], force=False)
                    return
            for action, remote in push_force_actions:
                if chosen is action:
                    self._push_branch(full_name, [remote], force=True)
                    return

    def _configured_remotes(self):
        graph_view = self._graph_view()
        if graph_view is None or graph_view.context is None:
            return []
        model = graph_view.context.model
        if model is None:
            return []
        return list(getattr(model, 'remotes', None) or [])

    def _push_branch(self, branch_name, remotes, force=False):
        graph_view = self._graph_view()
        if graph_view is None or graph_view.context is None:
            return
        context = graph_view.context
        model = context.model
        if model is None or not remotes:
            return

        def push_to_remotes():
            results = []
            for remote in remotes:
                try:
                    status, out, err = model.push(
                        remote,
                        local_branch=branch_name,
                        remote_branch=branch_name,
                        force=force,
                    )
                except Exception as exc:  # pragma: no cover - defensive
                    status, out, err = -1, '', str(exc)
                results.append((remote, status, out, err))
            return results

        def on_result(results):
            if not results:
                return
            any_failure = False
            for remote, status, out, err in results:
                cmd = 'git push %s %s' % (remote, branch_name)
                Interaction.log_status(status, out, err)
                if status != 0:
                    any_failure = True
                    Interaction.command_error(N_('Push failed'), cmd, status, out, err)
            if not any_failure:
                graph_view.merge_finished.emit()

        task = qtutils.SimpleTask(push_to_remotes)
        context.runtask.start(task, result=on_result)

    def _rename_branch(self, full_name, suggestion):
        graph_view = self._graph_view()
        if graph_view is None:
            return
        new_name, ok = _prompt_wide(
            N_('Enter new branch name'),
            title=N_('Rename "%s"') % full_name,
            text=suggestion,
            width_factor=4,
        )
        if not ok:
            return
        new_name = new_name.strip()
        if not new_name or new_name == full_name:
            return
        result = cmds.do(
            cmds.RenameBranch, graph_view.context, full_name, new_name
        )
        if result and result[0] == 0:
            graph_view.merge_finished.emit()


def _prompt_wide(msg, title, text='', width_factor=1):
    """Like qtutils.prompt, but with the dialog forced wider.

    width_factor multiplies a reference QInputDialog width.  We build the
    widget tree directly because QInputDialog ignores most width hints.
    """
    parent = qtutils.active_window()
    dialog = QtWidgets.QDialog(parent)
    dialog.setWindowTitle(title)
    label = QtWidgets.QLabel(msg)
    line_edit = QtWidgets.QLineEdit(text)
    line_edit.selectAll()
    buttons = QtWidgets.QDialogButtonBox(
        QtWidgets.QDialogButtonBox.Ok | QtWidgets.QDialogButtonBox.Cancel
    )
    buttons.accepted.connect(dialog.accept)
    buttons.rejected.connect(dialog.reject)
    layout = QtWidgets.QVBoxLayout(dialog)
    layout.addWidget(label)
    layout.addWidget(line_edit)
    layout.addWidget(buttons)
    reference = QtWidgets.QInputDialog(parent).sizeHint().width() or 280
    dialog.resize(int(reference * width_factor), dialog.sizeHint().height())
    accepted = dialog.exec_() == QtWidgets.QDialog.Accepted
    return line_edit.text(), accepted


def _branch_tip_basenames(context, oid):
    """Return de-duplicated basenames of files **changed by** the commit
    at ``oid`` (vs. its first parent, falling back to the empty tree for
    root commits) whose relative paths do not start with an underscore.

    Used to build a "Rename to" suggestion that tags a branch with the
    work introduced by its tip commit.

    Returns ``[]`` when no eligible files are found, in which case the
    caller hides the "Rename to" menu entry entirely.
    """

    @functools.wraps(func)
    def wrapped(*args, **kwargs):
        return decorator(func(action(*args, **kwargs)))

    return wrapped


def decorate(decorator, func) -> functools._Wrapped[..., Any, ..., Any]:
    """Decorate the result of `func` with `action`"""

    @functools.wraps(func)
    def decorated(*args, **kwargs):
        return decorator(func(*args, **kwargs))

    return decorated


def getenv(name: str, default: str | None = None) -> UStr | None:
    return decode(os.getenv(name, default))

    VERBOSE = bool(os.getenv('GIT_COLA_VERBOSE'))

    @classmethod
    def command(
        cls,
        title: TextType,
        cmd: list[TextType] | str,
        status: int,
        out: TextType,
        err: TextType,
    ) -> None:
        """Log a command and display error messages on failure"""
        cls.log_status(status, out, err)
        if status != 0:
            cls.command_error(title, cmd, status, out, err)

    @classmethod
    def command_error(
        cls,
        title: str,
        cmd: list[TextType] | str,
        status: int,
        out: TextType,
        err: TextType,
    ) -> None:
        """Display an error message for a failed command"""
        core.print_stderr(title)
        core.print_stderr('-' * len(title))
        core.print_stderr(cls.format_command_status(cmd, status))
        core.print_stdout('')
        if out:
            core.print_stdout(out)
        if err:
            core.print_stderr(err)

    @staticmethod
    def format_command_status(cmd: list[TextType] | str, status: int) -> str:
        return N_('"%(command)s" returned exit status %(status)d') % {
            'command': cmd,
            'status': status,
        }

    @staticmethod
    def format_out_err(out: core.UStr, err: core.UStr) -> str:
        """Format stdout and stderr into a single string"""
        details = out or ''
        if err:
            if details and not details.endswith('\n'):
                details += '\n'
            details += err
        return details

    @staticmethod
    def information(
        title: str,
        message: str | None = None,
        details: str | None = None,
        informative_text: str | None = None,
    ) -> None:
        if message is None:
            message = title
        scope = {}
        scope['title'] = title
        scope['title_dashes'] = '-' * len(title)
        scope['message'] = message
        scope['details'] = ('\n' + details) if details else ''
        scope['informative_text'] = (
            ('\n' + informative_text) if informative_text else ''
        )
        sys.stdout.write(
            """
%(title)s
%(title_dashes)s
%(message)s%(informative_text)s%(details)s\n"""
            % scope
        )
        sys.stdout.flush()

